def count_large_k_frequency_substrings(s,k):
    counts={};left=0;answer=0
    for char in s:
        counts[char]=counts.get(char,0)+1
        while counts[char]>=k:
            counts[s[left]]-=1;left+=1
        answer+=left
    return answer

